import React, { useState } from "react";
import axios from "axios";

const ImageProcessor = ({ colorblindType, mode }) => {
  const [original, setOriginal] = useState(null);
  const [processed, setProcessed] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleFile = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const url = URL.createObjectURL(file);
    setOriginal(url);
    setProcessed(null);

    const formData = new FormData();
    formData.append("file", file);
    formData.append("type", colorblindType);
    formData.append("mode", mode);

    setLoading(true);
    const res = await axios.post("http://localhost:5000/api/image", formData, {
      responseType: "blob",
    });
    setProcessed(URL.createObjectURL(res.data));
    setLoading(false);
  };

  return (
    <div style={styles.card}>
      <input type="file" accept="image/*" onChange={handleFile} />
      <div style={styles.grid}>
        {original && (
          <div style={styles.imageBox}>
            <h3>Original</h3>
            <img src={original} style={styles.image} />
          </div>
        )}
        {processed && (
          <div style={styles.imageBox}>
            <h3>Output</h3>
            <img src={processed} style={styles.image} />
          </div>
        )}
      </div>
      {loading && <p>Processing...</p>}
    </div>
  );
};

const styles = {
  card: {
    background: "#fff",
    padding: "20px",
    borderRadius: "12px",
    maxWidth: "100%",
    overflow: "hidden",
  },
  grid: {
    display: "flex",
    gap: "20px",
    marginTop: "20px",
    flexWrap: "wrap",
  },
  imageBox: {
    flex: "1 1 48%",
    textAlign: "center",
  },
  image: {
    width: "100%",
    maxHeight: "400px",
    objectFit: "contain",
    borderRadius: "8px",
  },
};

export default ImageProcessor;
